SELECT 'jl.party' k, COUNT(*) n FROM journal_lines jl LEFT JOIN parties p ON p.tenant_id=jl.tenant_id AND p.id=jl.party_id WHERE jl.party_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'jl.branch', COUNT(*) FROM journal_lines jl LEFT JOIN branches b ON b.tenant_id=jl.tenant_id AND b.id=jl.branch_id WHERE jl.branch_id IS NOT NULL AND b.id IS NULL
UNION ALL SELECT 'jl.account_company_mismatch', COUNT(*) FROM journal_lines jl JOIN journal_entries je ON je.tenant_id=jl.tenant_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.tenant_id=jl.tenant_id AND a.id=jl.account_id WHERE a.company_id<>je.company_id
UNION ALL SELECT 'sm.source_missing_SI', COUNT(*) FROM stock_movements sm LEFT JOIN sales_invoices si ON si.tenant_id=sm.tenant_id AND si.id=sm.source_id WHERE sm.source_type='SALES_INVOICE' AND si.id IS NULL
UNION ALL SELECT 'je.unbalanced_posted', COUNT(*) FROM journal_entries je WHERE je.status='POSTED' AND je.total_debit<>je.total_credit
UNION ALL SELECT 'je.lines_sum_mismatch', COUNT(*) FROM (SELECT je.id FROM journal_entries je JOIN journal_lines jl ON jl.tenant_id=je.tenant_id AND jl.journal_entry_id=je.id WHERE je.status='POSTED' GROUP BY je.id, je.total_debit, je.total_credit HAVING SUM(jl.debit)<>je.total_debit OR SUM(jl.credit)<>je.total_credit) x
UNION ALL SELECT 'sm.unitcost_x_qty_ne_total', COUNT(*) FROM stock_movements WHERE ROUND((qty_in+qty_out)*unit_cost,3)<>total_cost
UNION ALL SELECT 'ic.vs_movements_value', COUNT(*) FROM item_costs ic LEFT JOIN (SELECT tenant_id, company_id, item_id, SUM(qty_in-qty_out) q, SUM(CASE WHEN qty_in>0 THEN total_cost ELSE -total_cost END) v FROM stock_movements GROUP BY tenant_id, company_id, item_id) m ON m.tenant_id=ic.tenant_id AND m.company_id=ic.company_id AND m.item_id=ic.item_id WHERE COALESCE(m.q,0)<>ic.total_qty OR COALESCE(m.v,0)<>ic.total_value
UNION ALL SELECT 'tenant_tables_without_tenant_fk', COUNT(*) FROM information_schema.columns c WHERE c.table_schema='erp_dev' AND c.column_name='tenant_id' AND NOT EXISTS (SELECT 1 FROM information_schema.key_column_usage k WHERE k.table_schema='erp_dev' AND k.table_name=c.table_name AND k.column_name='tenant_id' AND k.referenced_table_name='tenants')
